package com.lapauseclub.manager.core;
import android.content.ContentValues;import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.database.sqlite.SQLiteOpenHelper;import org.json.JSONArray;import org.json.JSONObject;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.Locale;import java.util.UUID;
public final class CoreStore extends SQLiteOpenHelper{
 public static final String DB_NAME="la_pause_core_v16.db";private static final int DB_VERSION=7;private static final int MAX_SNAPSHOTS=20;public CoreStore(Context c){super(c,DB_NAME,null,DB_VERSION);setWriteAheadLoggingEnabled(true);}@Override public void onConfigure(SQLiteDatabase db){super.onConfigure(db);db.setForeignKeyConstraintsEnabled(true);}
 @Override public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE core_meta (key TEXT PRIMARY KEY NOT NULL,value TEXT NOT NULL)");db.execSQL("CREATE TABLE state_snapshots (id TEXT PRIMARY KEY NOT NULL,checksum_sha256 TEXT NOT NULL,state_json TEXT NOT NULL,source TEXT NOT NULL,legacy_schema_version INTEGER,data_revision INTEGER,created_at_ms INTEGER NOT NULL)");db.execSQL("CREATE INDEX idx_state_snapshots_created ON state_snapshots(created_at_ms DESC)");db.execSQL("CREATE TABLE resources_shadow (id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,resource_type TEXT NOT NULL,legacy_station_type TEXT,enabled INTEGER NOT NULL,sort_order INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL)");db.execSQL("CREATE TABLE domain_events (event_id TEXT PRIMARY KEY NOT NULL,event_type TEXT NOT NULL,entity_id TEXT,payload_json TEXT,event_at_ms INTEGER,legacy_revision INTEGER,imported_at_ms INTEGER NOT NULL)");db.execSQL("CREATE TABLE sync_outbox (event_id TEXT PRIMARY KEY NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,next_attempt_at_ms INTEGER,created_at_ms INTEGER NOT NULL,FOREIGN KEY(event_id) REFERENCES domain_events(event_id))");CoreDomainSchemaV2.create(db);CoreOperationalSchemaP1.create(db);CoreBusinessSchemaP1.create(db);CoreDeviceSchemaP2.create(db);CoreOwnerSchemaP3.create(db);CorePlayerSchemaP4.create(db);CoreSaasSchemaP5.create(db);putMeta(db,"migration_mode","DOMAIN_DUAL_WRITE");putMeta(db,"operating_mode","STANDALONE");putMeta(db,"authority_state","TABLET_PRIMARY");putMeta(db,"core_schema_version",String.valueOf(DB_VERSION));}
 @Override public void onUpgrade(SQLiteDatabase db,int o,int n){if(n!=DB_VERSION||o<1||o>DB_VERSION)throw new IllegalStateException("Unsupported non-destructive CoreStore migration: "+o+" -> "+n);db.beginTransaction();try{if(o<2){CoreDomainSchemaV2.create(db);CoreDomainSchemaV2.migrateShadowResources(db,System.currentTimeMillis());}if(o<3){CoreOperationalSchemaP1.create(db);CoreBusinessSchemaP1.create(db);}if(o<4)CoreDeviceSchemaP2.create(db);if(o<5)CoreOwnerSchemaP3.create(db);if(o<6)CorePlayerSchemaP4.create(db);if(o<7)CoreSaasSchemaP5.create(db);putMeta(db,"core_schema_version",String.valueOf(DB_VERSION));putMeta(db,"migration_mode","DOMAIN_DUAL_WRITE");db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public synchronized void bootstrapFromLegacy(String j){if(j==null||j.trim().isEmpty())return;mirror(j,"BOOTSTRAP");}public synchronized void mirrorLegacyState(String j){mirror(j,"LEGACY_SAVE");}
 private void mirror(String j,String source){if(j==null||j.trim().isEmpty())return;final JSONObject root;try{root=new JSONObject(j);}catch(Exception e){return;}final String h=sha256(j);final long n=System.currentTimeMillis();final int schema=root.optInt("schemaVersion",0);final JSONObject meta=root.optJSONObject("meta");final long rev=meta==null?0:meta.optLong("dataRevision",0);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{boolean snap=true;try(Cursor c=db.rawQuery("SELECT checksum_sha256 FROM state_snapshots ORDER BY created_at_ms DESC LIMIT 1",null)){if(c.moveToFirst()&&h.equals(c.getString(0)))snap=false;}if(snap){ContentValues v=new ContentValues();v.put("id","snapshot-"+UUID.randomUUID());v.put("checksum_sha256",h);v.put("state_json",j);v.put("source",source);v.put("legacy_schema_version",schema);v.put("data_revision",rev);v.put("created_at_ms",n);db.insertOrThrow("state_snapshots",null,v);db.execSQL("DELETE FROM state_snapshots WHERE id NOT IN (SELECT id FROM state_snapshots ORDER BY created_at_ms DESC LIMIT "+MAX_SNAPSHOTS+")");}mirrorStations(db,root.optJSONArray("stations"),n);importEvents(db,root.optJSONArray("outbox"),n);CoreDomainSchemaV2.dualWrite(db,root,rev,h,n);CoreOperationalSchemaP1.dualWrite(db,root,rev,h,n);CoreBusinessSchemaP1.dualWrite(db,root,rev,n);CoreDeviceSchemaP2.dualWrite(db,root,rev,n);CoreOwnerSchemaP3.dualWrite(db,root,rev,n);CorePlayerSchemaP4.dualWrite(db,root,rev,n);CoreSaasSchemaP5.dualWrite(db,root,rev,n);putMeta(db,"migration_mode","DOMAIN_DUAL_WRITE");putMeta(db,"legacy_schema_version",String.valueOf(schema));putMeta(db,"legacy_data_revision",String.valueOf(rev));putMeta(db,"last_mirror_checksum",h);putMeta(db,"last_mirror_at_ms",String.valueOf(n));db.setTransactionSuccessful();}finally{db.endTransaction();}}
 private static void mirrorStations(SQLiteDatabase db,JSONArray a,long n){if(a==null)return;db.delete("resources_shadow",null,null);for(int i=0;i<a.length();i++){JSONObject s=a.optJSONObject(i);if(s==null)continue;String id=s.optString("id","").trim();if(id.isEmpty())continue;String legacy=s.optString("type","CUSTOM"),type=s.optString("osResourceType",CoreDomainSchemaV2.mapResourceType(legacy));ContentValues v=new ContentValues();v.put("id",id);v.put("name",s.optString("name",id));v.put("resource_type",type);v.put("legacy_station_type",legacy);v.put("enabled",s.optBoolean("enabled",true)?1:0);v.put("sort_order",s.optInt("sort",i+1));v.put("updated_at_ms",n);db.insertWithOnConflict("resources_shadow",null,v,SQLiteDatabase.CONFLICT_REPLACE);}}
 private static void importEvents(SQLiteDatabase db,JSONArray a,long n){if(a==null)return;for(int i=0;i<a.length();i++){JSONObject e=a.optJSONObject(i);if(e==null)continue;String id=e.optString("id","").trim();if(id.isEmpty())continue;ContentValues v=new ContentValues();v.put("event_id",id);v.put("event_type",e.optString("type","legacy.unknown"));String entity=e.optString("entityId","");if(!entity.isEmpty())v.put("entity_id",entity);Object p=e.opt("payload");v.put("payload_json",p==null||p==JSONObject.NULL?null:String.valueOf(p));v.put("event_at_ms",e.optLong("at",n));v.put("legacy_revision",e.optLong("revision",0));v.put("imported_at_ms",n);long inserted=db.insertWithOnConflict("domain_events",null,v,SQLiteDatabase.CONFLICT_IGNORE);if(inserted!=-1){ContentValues o=new ContentValues();o.put("event_id",id);o.put("status","PENDING");o.put("attempts",0);o.put("created_at_ms",n);db.insertWithOnConflict("sync_outbox",null,o,SQLiteDatabase.CONFLICT_IGNORE);}}}
 public synchronized String recoverLatestValidStateJson(){SQLiteDatabase db=getReadableDatabase();try(Cursor c=db.rawQuery("SELECT state_json,checksum_sha256 FROM state_snapshots ORDER BY created_at_ms DESC LIMIT "+MAX_SNAPSHOTS,null)){while(c.moveToNext()){String j=c.getString(0),h=c.getString(1);try{new JSONObject(j);if(h.equals(sha256(j)))return j;}catch(Exception ignored){}}}return "";}
 public synchronized JSONObject getTimelineJson(){JSONObject out=new JSONObject();JSONArray ss=new JSONArray(),ev=new JSONArray();SQLiteDatabase db=getReadableDatabase();try(Cursor c=db.rawQuery("SELECT id,source,data_revision,created_at_ms,checksum_sha256 FROM state_snapshots ORDER BY created_at_ms DESC LIMIT 20",null)){while(c.moveToNext()){JSONObject x=new JSONObject();x.put("id",c.getString(0));x.put("source",c.getString(1));x.put("revision",c.getLong(2));x.put("createdAtMs",c.getLong(3));x.put("checksum",c.getString(4));ss.put(x);}}catch(Exception ignored){}try(Cursor c=db.rawQuery("SELECT event_id,event_type,entity_id,event_at_ms,legacy_revision FROM domain_events ORDER BY imported_at_ms DESC LIMIT 40",null)){while(c.moveToNext()){JSONObject x=new JSONObject();x.put("eventId",c.getString(0));x.put("eventType",c.getString(1));x.put("entityId",c.isNull(2)?JSONObject.NULL:c.getString(2));x.put("eventAtMs",c.getLong(3));x.put("revision",c.getLong(4));ev.put(x);}}catch(Exception ignored){}try{out.put("snapshots",ss);out.put("events",ev);}catch(Exception ignored){}return out;}
 public synchronized JSONObject getStatusJson(){SQLiteDatabase db=getReadableDatabase();JSONObject out=new JSONObject();try{JSONObject a2=CoreDomainSchemaV2.status(db),p1=CoreOperationalSchemaP1.status(db),biz=CoreBusinessSchemaP1.status(db),p2=CoreDeviceSchemaP2.status(db),p3=CoreOwnerSchemaP3.status(db),p4=CorePlayerSchemaP4.status(db),p5=CoreSaasSchemaP5.status(db);JSONArray rr=a2.optJSONArray("resourceRegistry");out.put("coreVersion","p5-dev.1");out.put("dbSchemaVersion",DB_VERSION);out.put("migrationMode",getMeta(db,"migration_mode","DOMAIN_DUAL_WRITE"));out.put("operatingMode",getMeta(db,"operating_mode","STANDALONE"));out.put("authorityState",getMeta(db,"authority_state","TABLET_PRIMARY"));out.put("legacySchemaVersion",parseLong(getMeta(db,"legacy_schema_version","0")));out.put("legacyDataRevision",parseLong(getMeta(db,"legacy_data_revision","0")));out.put("lastMirrorAtMs",parseLong(getMeta(db,"last_mirror_at_ms","0")));out.put("snapshotCount",scalar(db,"SELECT COUNT(*) FROM state_snapshots"));out.put("resourceCount",rr==null?0:rr.length());out.put("eventCount",scalar(db,"SELECT COUNT(*) FROM domain_events"));out.put("pendingSyncCount",scalar(db,"SELECT COUNT(*) FROM sync_outbox WHERE status='PENDING'"));out.put("checkpointCount",scalar(db,"SELECT COUNT(*) FROM migration_checkpoints"));out.put("venueProfile",a2.optJSONObject("venueProfile"));out.put("resourceRegistry",rr);out.put("domainAuthority",a2.optJSONArray("domainAuthority"));out.put("normalizedDomains",a2.optJSONArray("normalizedDomains"));out.put("p1Operational",p1);out.put("p1Business",biz);out.put("p2Device",p2);out.put("p3Owner",p3);out.put("p4Player",p4);out.put("p5Saas",p5);out.put("authorityProgress","P1_P2_P3_P4_P5_DUAL_WRITE");out.put("legacyStillAuthoritative",true);out.put("networkRequired",false);}catch(Exception ignored){}return out;}
 public synchronized String getOperatingMode(){return getMeta(getReadableDatabase(),"operating_mode","STANDALONE");}public synchronized void setOperatingMode(String m){String x=m==null?"":m.trim().toUpperCase(Locale.ROOT);if(!"STANDALONE".equals(x)&&!"CONNECTED_LOCAL".equals(x))throw new IllegalArgumentException("Unsupported operating mode");SQLiteDatabase db=getWritableDatabase();putMeta(db,"operating_mode",x);putMeta(db,"authority_state","TABLET_PRIMARY");}
 private static void putMeta(SQLiteDatabase db,String k,String x){ContentValues v=new ContentValues();v.put("key",k);v.put("value",x==null?"":x);db.insertWithOnConflict("core_meta",null,v,SQLiteDatabase.CONFLICT_REPLACE);}private static String getMeta(SQLiteDatabase db,String k,String f){try(Cursor c=db.rawQuery("SELECT value FROM core_meta WHERE key=?",new String[]{k})){return c.moveToFirst()?c.getString(0):f;}}private static long scalar(SQLiteDatabase db,String q){try(Cursor c=db.rawQuery(q,null)){return c.moveToFirst()?c.getLong(0):0;}}private static long parseLong(String x){try{return Long.parseLong(x);}catch(Exception e){return 0;}}public static String sha256(String x){try{MessageDigest d=MessageDigest.getInstance("SHA-256");byte[] b=d.digest(x.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder(b.length*2);for(byte z:b)s.append(String.format(Locale.ROOT,"%02x",z&0xff));return s.toString();}catch(Exception e){throw new IllegalStateException("SHA-256 unavailable",e);}}
}
